    { id = "item:277491:description", html = false,
      ja = "$D1の間、対象のElementalがあなたの呪文から受けるダメージを$N1%増加させます。レベル$N3以下の敵にのみ効果があります。",
      out = "$D1の間、対象のエレメンタルがあなたの呪文から受けるダメージを$N1%増加させます。レベル$N3以下の敵にのみ効果があります。" },
    { id = "item:281043:description", html = false,
      ja = "Bundle of Herbs、Bundle of Dried Cedar Twigs、Sinew Thread、Ceremonial Flint and Tinderを組み合わせてPrepared Incenseを作ります。",
      out = "バンドル・オブ・ハーブ、バンドル・オブ・ドライド・シーダー・トゥイッグ、シニュー・スレッド、セレモニアル・フリント・アンド・ティンダーを組み合わせてプリペアド・インセンスを作ります。" },
