    { id = "ui:FactionDescription:2641:text", html = false,
      ja = "急ぎ結成されたドルイドの集団で、AllianceとHordeの双方と協力してNightmare Incursionsを食い止めようとしている。",
      out = "急ぎ結成されたドルイドの集団で、アライアンスとホードの双方と協力してナイトメア・インカージョンを食い止めようとしている。" },
    { id = "ui:FactionDescription:76:text", html = false,
      ja = "Thrallが築いたこのHordeの首都には、Durotarの誇り高きオークの氏族が数多く暮らしている。",
      out = "スロールが築いたこのホードの首都には、デュロターの誇り高きオークの氏族が数多く暮らしている。" },
